from pathlib import Path

root=Path(__file__).resolve().parents[2]
base=(root/'public/previews/kho-xe.html').read_text(encoding='utf-8')
css=r'''
html,body{overflow:hidden}.app{display:grid;grid-template-columns:74px minmax(0,1fr);grid-template-rows:1fr;height:100vh}.rail{grid-row:1}.photo-workspace{height:100vh;display:flex;flex-direction:column;min-width:0;background:#fff}.photo-header{padding:28px 32px 22px;display:flex;justify-content:space-between;align-items:center}.photo-header h1{font-size:28px}.photo-header p{font-size:12px;color:#8a9ab0;margin:9px 0 0}.photo-header .caption{font-size:11px;color:#91a1b7}.photo-toolbar{display:flex;align-items:center;gap:12px;padding:0 32px 19px}.photo-toolbar .search{max-width:540px;height:42px}.photo-toolbar input{font-size:12px}.photo-toolbar select{font-size:12px;color:#667c9b;padding:11px 13px;border:1px solid #dce4ef;border-radius:6px;background:white}.photo-toolbar .result{margin-left:auto;color:#8b9bb0;font-size:11px}.photo-tabs{display:flex;gap:28px;margin:0 32px 20px;border-bottom:1px solid var(--line)}.photo-tabs button{padding:0 0 13px;font-size:12px;color:#8090a7}.photo-tabs button.on{color:#205eb4;border-bottom:2px solid #205eb4}.photo-tabs small{font-size:10px;margin-left:7px;color:#94a4b9}.photo-body{display:flex;gap:26px;flex:1;min-height:0;margin:0 32px}.photo-gallery{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px;align-content:start;flex:1;min-width:0;overflow:auto;scrollbar-width:thin;padding:2px 3px 16px 1px}.photo-card{position:relative;display:block;border:1px solid #e2e8f1;border-radius:7px;background:white;padding:18px 20px;text-align:left;min-width:0}.photo-card:hover{border-color:#a3bbdf}.photo-card.selected{border-color:#719bd8;background:#f7faff;box-shadow:0 0 0 1px #719bd8}.photo-card.selected:after{content:'✓';position:absolute;right:16px;top:49px;background:#2967b7;color:white;border-radius:50%;height:18px;width:18px;display:grid;place-items:center;font-size:11px}.photo-card .card-heading{display:flex;justify-content:space-between;gap:9px;align-items:center}.photo-card .card-heading h3{font-size:19px;margin:0;font-weight:600}.photo-card h3 small{font-size:13px;font-weight:400;color:#8092ad;margin-left:5px}.photo-card .status{font-size:10px}.photo-card img{display:block;width:100%;height:145px;object-fit:contain;margin:7px 0 8px}.photo-card .car-vin{color:#577196;font-family:Consolas,monospace;font-size:11px;letter-spacing:.2px}.photo-card .car-color{color:#8b9bb0;font-size:11px;margin-top:9px}.photo-card .car-footer{display:flex;justify-content:space-between;align-items:center;padding-top:12px;margin-top:12px;border-top:1px solid var(--line);font-size:11px;color:#7e91ac}.photo-card .car-footer strong{font-weight:500;color:#344f72}.photo-card .row-specs{display:none}.photo-bottom{display:flex;gap:24px;align-items:center;margin:0 32px;border-top:1px solid var(--line);height:88px;flex-shrink:0}.photo-bottom img{width:110px;height:70px;object-fit:contain}.photo-bottom h3{font-size:19px;margin:0 0 8px}.photo-bottom h3 small{color:#8294af;font-weight:400;font-size:13px;margin-left:6px}.photo-bottom .bottom-vin{font-family:Consolas,monospace;font-size:11px;color:#8395af}.bottom-field{border-left:1px solid var(--line);padding-left:24px}.bottom-field label{display:block;font-size:10px;color:#8d9eb4;margin-bottom:8px}.bottom-field span{font-size:12px}.photo-bottom .bottom-actions{display:flex;gap:8px;margin-left:auto}.photo-workspace footer{display:flex;justify-content:space-between;margin:0;padding:12px 32px;border-top:1px solid var(--line);color:#99a9be;font-size:10px}.photo-workspace footer b{font-weight:500;letter-spacing:2px}.photo-panel{width:355px;flex-shrink:0;border-left:1px solid var(--line);padding-left:25px;overflow:auto;scrollbar-width:thin}.photo-panel h4{font-size:16px;margin:0 0 7px;font-weight:600}.photo-panel .panel-note{color:#95a3b7;font-size:11px}.photo-panel img{width:100%;height:170px;object-fit:contain;margin:20px 0 12px}.photo-panel h3{font-size:31px;margin:0 0 12px}.photo-panel h3 small{font-size:19px;color:#8394ac;font-weight:400}.photo-panel .panel-vin{font-family:Consolas,monospace;color:#6580a3;font-size:12px;margin-bottom:20px}.photo-panel .data-row{font-size:12px;min-height:47px}.photo-panel .btn{width:100%;margin-top:19px}.photo-panel .note{font-size:11px}.photo-empty{color:#8496ae;padding:35px;font-size:13px}.variant-13 .photo-gallery{grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.variant-13 .photo-card{display:grid;grid-template-columns:46% 54%;grid-template-rows:auto 1fr auto;padding:20px 22px;min-height:192px}.variant-13 .photo-card img{grid-column:1;grid-row:1/4;height:145px;padding-right:22px;margin:0;align-self:center}.variant-13 .card-heading{grid-column:2;grid-row:1}.variant-13 .car-info{grid-column:2;grid-row:2;align-self:center}.variant-13 .car-footer{grid-column:2;grid-row:3;margin-top:6px;padding-top:11px}.variant-13 .photo-card.selected:after{right:auto;left:17px;top:17px}.variant-14 .photo-gallery{display:flex;flex-direction:column;gap:0}.variant-14 .photo-card{display:grid;grid-template-columns:230px 1.05fr 1.4fr .9fr 1fr;align-items:center;gap:28px;border:0;border-radius:0;border-bottom:1px solid var(--line);min-height:128px;padding:12px 22px;flex-shrink:0}.variant-14 .photo-card:first-child{border-top:1px solid var(--line)}.variant-14 .photo-card.selected{box-shadow:inset 3px 0 #2867bd;background:#edf3fe}.variant-14 .photo-card img{grid-column:1;grid-row:1;height:105px;margin:0}.variant-14 .card-heading{grid-column:2;grid-row:1;display:block}.variant-14 .card-heading h3{font-size:22px}.variant-14 .card-heading .status{margin-top:14px;font-size:11px}.variant-14 .car-info{grid-column:3;grid-row:1}.variant-14 .car-vin{font-size:12px}.variant-14 .car-color{margin-top:13px;font-size:12px}.variant-14 .car-footer{grid-column:4;grid-row:1;display:block;margin:0;padding:0;border:0;font-size:12px}.variant-14 .car-footer strong{display:block;margin-top:13px}.variant-14 .row-specs{display:block;grid-column:5;grid-row:1;border-left:1px solid var(--line);padding-left:26px;color:#8497b1;font-size:11px;line-height:2}.variant-14 .row-specs b{font-size:12px;font-weight:400;color:#3c5678}.variant-14 .photo-card.selected:after{left:12px;right:auto;top:12px}.visual-list-head{display:grid;grid-template-columns:230px 1.05fr 1.4fr .9fr 1fr;gap:28px;padding:12px 22px;background:#fbfcfe;color:#899ab1;font-size:11px;border-top:1px solid var(--line)}.variant-15 .photo-gallery{grid-template-columns:repeat(3,minmax(0,1fr));gap:17px}.variant-15 .photo-card img{height:145px}.variant-15 .photo-bottom{display:none}.variant-15 .photo-card .card-heading h3{font-size:18px}.variant-15 .photo-body{margin-bottom:16px}.model-shelf{border:1px solid #e3e9f1;border-radius:6px;padding:16px 20px;min-width:0;background:white}.model-shelf.has-selection{border-color:#8caddd;background:#f8fbff}.shelf-title{display:flex;justify-content:space-between;align-items:center}.shelf-title h3{font-size:21px;margin:0;font-weight:600}.shelf-title span{font-size:11px;color:#8b9db5}.shelf-image{padding:0;border:0;display:block;width:100%;cursor:pointer}.shelf-image img{width:100%;height:115px;object-fit:contain;display:block;margin:6px 0}.shelf-caption{display:flex;justify-content:space-between;color:#8b9cb2;font-size:10px;margin-bottom:9px}.vin-choice{display:flex;justify-content:space-between;align-items:center;gap:10px;width:100%;border-top:1px solid var(--line);padding:10px 0;font-size:11px;text-align:left;color:#5f799b}.vin-choice.selected{color:#205eb4;font-weight:600}.vin-choice .version-tag{font-size:10px;color:#8295af;font-weight:400}.vin-choice .status{font-size:10px;font-weight:400}.variant-16 .photo-gallery{grid-template-columns:repeat(3,minmax(0,1fr));gap:17px;grid-auto-rows:280px}.variant-16 .photo-bottom{height:83px}.variant-16 .photo-tabs{margin-bottom:16px}.variant-16 .photo-header{padding-top:24px;padding-bottom:18px}
'''
js=r'''
const variant='VARIANT';let photoQuery='',photoStatus='',photoModel='';
const rail=document.querySelector('.rail').outerHTML;
document.body.innerHTML=`<div class="app">${rail}<section class="photo-workspace variant-${variant}"><header class="photo-header"><div><h1>Kho xe <small>8</small></h1><p>VinFast Thuận An <span style="margin:0 8px">·</span> Chọn xe theo hình ảnh</p></div><span class="caption">Dữ liệu minh họa · 29/10/2026</span></header><div class="photo-toolbar"><label class="search">${icon('search')}<input id="search" placeholder="Tìm dòng xe, VIN, phiên bản, màu ngoại thất…" aria-label="Tìm xe"></label><select id="photo-model" aria-label="Dòng xe"><option value="">Tất cả dòng xe</option>${['VF 3','VF 5','VF 6','VF 7','VF 8','LIMO'].map(m=>`<option>${m}</option>`).join('')}</select><button class="btn" id="filter-demo">${icon('pin')} Kho Thuận An</button><span class="result" id="count">8 / 8 xe</span></div><div class="photo-tabs" id="photo-tabs"></div><div class="photo-body"><div class="photo-gallery" id="gallery"></div><aside class="photo-panel" id="photo-panel" hidden></aside></div><div class="photo-bottom" id="photo-bottom"></div><footer><span>MẪU VARIANT · TITLE</span><b>© 2026 ORDER MANAGEMENT</b></footer></section></div><div class="toast" id="toast" role="status" hidden></div>`;
function visibleCars(){return cars.map((c,i)=>({...c,i})).filter(c=>`${c.model} ${c.version} ${c.vin} ${c.color}`.toLowerCase().includes(photoQuery)&&(!photoStatus||c.status===photoStatus)&&(!photoModel||c.model===photoModel))}
function photoCard(c){return `<button class="photo-card ${c.i===selected?'selected':''}" data-index="${c.i}" aria-pressed="${c.i===selected}"><div class="card-heading"><h3>${c.model}<small>${c.version}</small></h3><span class="status" style="--tone:${tone(c.status)}">${c.status}</span></div><img src="../pictures/${c.image}.webp" alt="Chọn ${c.model} ${c.version}, VIN ${c.vin}"><div class="car-info"><div class="car-vin">${c.vin}</div><div class="car-color"><i class="swatch"></i>${c.color} · Black</div></div><div class="car-footer"><span>${c.park}</span><strong>Tồn ${c.age} ngày</strong></div><div class="row-specs">Ngày nhập kho<br><b>${c.date}</b><br>Hồ sơ COC · Đã tiếp nhận</div></button>`}
function renderChosen(){const c={...cars[selected],i:selected};$('photo-bottom').innerHTML=`<img src="../pictures/${c.image}.webp" alt="${c.model}"><div><h3><span id="${variant==='15'?'bottom-model':'model'}">${c.model}</span><small>${c.version}</small></h3><div class="bottom-vin">${c.vin}</div></div><div class="bottom-field"><label>Vị trí đỗ</label><span>${c.park}</span></div><div class="bottom-field"><label>Ngày nhập kho</label><span>${c.date}</span></div><div class="bottom-field"><label>Hồ sơ COC</label><span>Đã tiếp nhận</span></div><div class="bottom-field"><label>Trạng thái</label><span style="color:${tone(c.status)}">${c.status}</span></div><div class="bottom-actions"><button class="btn" data-action="Chi tiết xe">Chi tiết xe ↗</button><button class="btn primary" data-action="Giữ xe (24h)" ${c.status==='Chưa ghép'?'':'disabled'}>Giữ xe (24h)</button></div>`;
if(variant==='15'){$('photo-panel').hidden=false;$('photo-panel').innerHTML=`<h4>Xe đang chọn</h4><span class="panel-note">Bấm ảnh trong danh sách để chọn xe</span><img src="../pictures/${c.image}.webp" alt="${c.model}"><h3><span id="model">${c.model}</span> <small>${c.version}</small></h3><div class="panel-vin">${c.vin}</div><div class="data-row"><span>Trạng thái</span><span class="status" style="--tone:${tone(c.status)}">${c.status}</span></div><div class="data-row"><span>Ngoại thất</span><span>${c.color}</span></div><div class="data-row"><span>Nội thất</span><span>Black</span></div><div class="data-row"><span>Vị trí đỗ</span><span>${c.park}</span></div><div class="data-row"><span>Ngày nhập</span><span>${c.date}</span></div><div class="data-row"><span>Tuổi tồn</span><span>${c.age} ngày</span></div><div class="data-row"><span>Hồ sơ COC</span><span>Đã tiếp nhận</span></div><button class="btn primary" data-action="Giữ xe (24h)" ${c.status==='Chưa ghép'?'':'disabled'}>Giữ xe (24h)</button><p class="note">Thông tin xe và thao tác trong bản mẫu dùng dữ liệu minh họa.</p>`}
document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>toast('Mẫu thao tác '+b.dataset.action+' · Chưa ghi vào hệ thống'))}
function renderList(){const items=visibleCars();let markup='';if(variant==='16'){for(const m of ['VF 3','VF 5','VF 6','VF 7','VF 8','LIMO']){const group=items.filter(c=>c.model===m);if(!group.length)continue;markup+=`<section class="model-shelf ${group.some(c=>c.i===selected)?'has-selection':''}"><div class="shelf-title"><h3>${m}</h3><span>${group.length} xe trong kho</span></div><button class="shelf-image" data-pick="${group[0].i}" aria-label="Chọn dòng ${m}"><img src="../pictures/${group[0].image}.webp" alt="${m}"></button><div class="shelf-caption"><span>White (CE18) · Black</span><span>Chọn VIN bên dưới</span></div>${group.map(c=>`<button class="vin-choice ${c.i===selected?'selected':''}" data-index="${c.i}"><span>${c.vin} <span class="version-tag">· ${c.version}</span></span><span class="status" style="--tone:${tone(c.status)}">${c.status}</span></button>`).join('')}</section>`}}else markup=(variant==='14'?'<div class="visual-list-head"><span>Ảnh xe</span><span>Dòng xe / Trạng thái</span><span>Số VIN / Màu xe</span><span>Vị trí / Tuổi tồn</span><span>Thông tin kho</span></div>':'')+items.map(photoCard).join('');$('gallery').innerHTML=items.length?markup:'<div class="photo-empty">Không tìm thấy xe phù hợp.</div>';$('count').textContent=`${items.length} / 8 xe`;$('photo-tabs').innerHTML=['','Chưa ghép','Đang giữ','Đã ghép'].map(s=>`<button data-status="${s}" class="${s===photoStatus?'on':''}">${s||'Tất cả xe'}<small>${s?cars.filter(c=>c.status===s).length:8}</small></button>`).join('');document.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{photoStatus=b.dataset.status;renderList()});document.querySelectorAll('[data-index],[data-pick]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.index??b.dataset.pick);renderList()});renderChosen()}
$('search').oninput=e=>{photoQuery=e.target.value.toLowerCase();renderList()};$('photo-model').onchange=e=>{photoModel=e.target.value;renderList()};$('filter-demo').onclick=()=>toast('Cả 8 xe minh họa đều thuộc Kho Thuận An');document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>toast('Bạn đang xem mẫu Kho xe'));renderList();
'''
titles={'12':'Lưới ảnh lớn 4 cột','13':'Thẻ xe ngang 2 cột','14':'Danh sách có ảnh lớn','15':'Lưới ảnh & khung chọn xe','16':'Chọn ảnh dòng xe rồi chọn VIN'}
for n,title in titles.items():
    html=base.replace('</style>',css+'</style>').replace('</body>','<script>'+js.replace('VARIANT',n).replace('TITLE',title.upper())+'</script></body>')
    html=html.replace('Kho xe · Mẫu giao diện','Kho xe · Mẫu '+n+' · '+title)
    (root/('public/previews/kho-xe-mau-'+n+'.html')).write_text(html,encoding='utf-8')
    print('Created photo variant '+n)
